"use client";

import React, { useState, useRef, useEffect, useCallback } from "react";
import { Document, Page, pdfjs } from "react-pdf";
import HTMLFlipBook from "react-pageflip";
import "react-pdf/dist/Page/AnnotationLayer.css";
import "react-pdf/dist/Page/TextLayer.css";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import {
  ChevronLeft,
  ChevronRight,
  ZoomIn,
  ZoomOut,
  Maximize,
  Minimize2,
  Search,
  Home,
  Share2
} from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import Link from "next/link";

const PDF_URL = "/Pdf/Sagar and Pratiksha_compressed (1).pdf";
const VIDEO_EFFECT_URL = "/20260204-1122-21.2650973.mp4";
const ALBUMS_API_BASE = "https://pk.thetechthingy.com/api/v1";

type AlbumResponse = {
  _id: string;
  name: string;
  event_date: string;
  userId: string;
  url: string;
  createdAt: string;
  updatedAt: string;
  __v: number;
};

if (typeof window !== "undefined") {
  pdfjs.GlobalWorkerOptions.workerSrc = `https://unpkg.com/pdfjs-dist@${pdfjs.version}/build/pdf.worker.min.mjs`;
}

type PdfPageDimensions = { width: number; height: number };

const PDFFlipPage = React.forwardRef<
  HTMLDivElement,
  {
    pageNumber: number;
    width: number;
    height: number;
    pdfPageDimensions: PdfPageDimensions | null;
  }
>(({ pageNumber, width, height, pdfPageDimensions }, ref) => {
  const scale = pdfPageDimensions
    ? Math.min(
        width / pdfPageDimensions.width,
        height / pdfPageDimensions.height
      )
    : 1;
  const renderWidth = pdfPageDimensions
    ? pdfPageDimensions.width * scale
    : width;

  return (
    <div
      ref={ref}
      className="w-full h-full flex items-center justify-center overflow-hidden bg-[#1a1a1a]"
      style={{
        boxShadow: "inset 0 0 20px rgba(0,0,0,0.5)",
      }}
    >
      <div className="w-full h-full flex items-center justify-center overflow-hidden bg-white shadow-xl">
        <Page
          pageNumber={pageNumber}
          width={renderWidth}
          renderTextLayer={false}
          renderAnnotationLayer={false}
        />
      </div>
    </div>
  );
});
PDFFlipPage.displayName = "PDFFlipPage";

export function AlbumPageClient() {
  const [albumId, setAlbumId] = useState("");
  const [coupleName, setCoupleName] = useState("");
  const [eventDate, setEventDate] = useState("");
  const [email, setEmail] = useState("");
  const [isFinding, setIsFinding] = useState(false);
  const [albumData, setAlbumData] = useState<AlbumResponse | null>(null);
  const [findError, setFindError] = useState<string | null>(null);

  const [currentPage, setCurrentPage] = useState(1);
  const [zoom, setZoom] = useState(1);
  const [shareUrl, setShareUrl] = useState("");
  const [isFlipping, setIsFlipping] = useState(false);
  const [numPages, setNumPages] = useState<number | null>(null);
  const [pdfPageDimensions, setPdfPageDimensions] = useState<PdfPageDimensions | null>(null);
  
  const [pageWidth, setPageWidth] = useState(0);
  const [pageHeight, setPageHeight] = useState(0);
  
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);

  const viewerRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const bookRef = useRef<{ pageFlip: () => { flipNext: () => void; flipPrev: () => void } }>(null);
  const pinchRef = useRef<{ distance: number; zoom: number } | null>(null);

  const getTouchDistance = (touches: React.TouchList | TouchList) =>
    Math.hypot(
      touches[1].clientX - touches[0].clientX,
      touches[1].clientY - touches[0].clientY
    );

  const handleTouchStart = (e: React.TouchEvent) => {
    if (e.touches.length === 2) {
      pinchRef.current = {
        distance: getTouchDistance(e.touches),
        zoom,
      };
    }
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    if (e.touches.length < 2) pinchRef.current = null;
  };

  useEffect(() => {
    setShareUrl(typeof window !== "undefined" ? window.location.href : "");
  }, []);

  useEffect(() => {
    const onFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener("fullscreenchange", onFullscreenChange);
    return () => document.removeEventListener("fullscreenchange", onFullscreenChange);
  }, []);

  useEffect(() => {
    const el = viewerRef.current;
    if (!el) return;
    const ro = new ResizeObserver((entries) => {
      const { width, height } = entries[0]?.contentRect ?? {};
      if (typeof width === "number" && width > 0 && typeof height === "number" && height > 0) {
        let targetHeight = height;
        let targetWidth = targetHeight * (3/4);
        
        if (targetWidth * 2 > width) {
            targetWidth = width / 2;
            targetHeight = targetWidth * (4/3);
        }
        
        setPageWidth(targetWidth);
        setPageHeight(targetHeight);
      }
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  useEffect(() => {
    const el = viewerRef.current;
    if (!el) return;
    const getDistance = (touches: TouchList) =>
      Math.hypot(
        touches[1].clientX - touches[0].clientX,
        touches[1].clientY - touches[0].clientY
      );
    const onTouchMove = (e: TouchEvent) => {
      if (e.touches.length === 2 && pinchRef.current) {
        e.preventDefault();
        const distance = getDistance(e.touches);
        const scale = distance / pinchRef.current.distance;
        const newZoom = Math.min(
          3,
          Math.max(0.5, pinchRef.current.zoom * scale)
        );
        setZoom(newZoom);
        pinchRef.current = { distance, zoom: newZoom };
      }
    };
    el.addEventListener("touchmove", onTouchMove, { passive: false });
    return () => el.removeEventListener("touchmove", onTouchMove);
  }, []);

  const totalPages = numPages ?? 1;

  const onFlip = useCallback((e: { data: number }) => {
    setCurrentPage(typeof e.data === "number" ? e.data + 1 : 1);
  }, []);

  const onFlipState = useCallback((e: { data: string }) => {
    setIsFlipping(e.data === "flipping");
  }, []);

  const goPrev = () => {
    if (currentPage <= 1 || isFlipping) return;
    bookRef.current?.pageFlip()?.flipPrev();
  };

  const goNext = () => {
    if (currentPage >= totalPages || isFlipping) return;
    bookRef.current?.pageFlip()?.flipNext();
  };
  const zoomIn = () => setZoom((z) => Math.min(3, z + 0.25));
  const zoomOut = () => setZoom((z) => Math.max(0.5, z - 0.25));

  const toggleFullscreen = () => {
    if (!containerRef.current) return;
    if (!document.fullscreenElement) {
      containerRef.current.requestFullscreen?.();
    } else {
      document.exitFullscreen?.();
    }
  };

  const handleFindAlbum = async (e: React.FormEvent) => {
    e.preventDefault();
    setFindError(null);
    const eventName = (albumId.trim() || coupleName.trim()) || undefined;
    const userEmail = email.trim() || undefined;

    if (!eventName && !userEmail) {
      setFindError("Please enter an Album ID, the couple's name, or your email.");
      return;
    }

    setIsFinding(true);
    try {
      const res = await fetch(`${ALBUMS_API_BASE}/albums/getAlbum`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          event_name: eventName,
          email: userEmail,
          event_date: eventDate || undefined,
        }),
      });
      const data = await res.json();
      if (!res.ok) {
        setFindError(data?.message || "Could not find your album. Please check your details.");
        setAlbumData(null);
        return;
      }
      setAlbumData(data as AlbumResponse);
      setIsSearchOpen(false);
    } catch {
      setFindError("Something went wrong. Please try again.");
      setAlbumData(null);
    } finally {
      setIsFinding(false);
    }
  };

  return (
    <div ref={containerRef} className="relative h-screen w-screen overflow-hidden bg-black text-white font-sans">
      <div className="pointer-events-none absolute inset-0 z-0 overflow-hidden">
        <video
          autoPlay
          muted
          loop
          playsInline
          className="h-full w-full object-cover opacity-30"
          aria-hidden
        >
          <source src={VIDEO_EFFECT_URL} type="video/mp4" />
        </video>
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-transparent via-black/40 to-black pointer-events-none z-[1]" />
      </div>

      <div className="absolute top-0 left-0 w-full p-4 sm:p-6 flex justify-between items-start z-50 pointer-events-none">
        <div className="pointer-events-auto max-w-[60%]">
          <h1 className="text-xl sm:text-3xl font-headline font-bold drop-shadow-lg tracking-tight">
            {albumData ? albumData.name : "Demo Album"}
          </h1>
          <p className="text-xs sm:text-sm text-gray-300 drop-shadow-md">
            {albumData?.event_date 
              ? new Date(albumData.event_date).toLocaleDateString()
              : "Experience your memories"}
          </p>
        </div>
        
        <div className="flex flex-col gap-3 pointer-events-auto">
          <Link href="/">
            <Button variant="secondary" size="icon" className="rounded-full bg-white/10 hover:bg-white/20 text-white border-white/20 backdrop-blur-md">
              <Home className="h-4 w-4 sm:h-5 sm:w-5" />
            </Button>
          </Link>

          <Dialog open={isSearchOpen} onOpenChange={setIsSearchOpen}>
            <DialogTrigger asChild>
              <Button variant="secondary" size="icon" className="rounded-full bg-white/10 hover:bg-white/20 text-white border-white/20 backdrop-blur-md" title="Find Album">
                <Search className="h-4 w-4 sm:h-5 sm:w-5" />
              </Button>
            </DialogTrigger>
            <DialogContent className="sm:max-w-[425px] bg-zinc-950 text-white border-zinc-800">
              <DialogHeader>
                <DialogTitle>Find Your Personal Album</DialogTitle>
                <DialogDescription className="text-zinc-400">
                  Enter your Album ID, couple's name, or email to access your album.
                </DialogDescription>
              </DialogHeader>
              <form onSubmit={handleFindAlbum} className="space-y-4 pt-4">
                <div className="space-y-2">
                  <Label htmlFor="albumId" className="text-zinc-300">Album ID</Label>
                  <Input
                    id="albumId"
                    placeholder="e.g. ALB-XXXX"
                    value={albumId}
                    onChange={(e) => setAlbumId(e.target.value)}
                    className="bg-zinc-900 border-zinc-800 text-white placeholder:text-zinc-600"
                  />
                </div>
                <div className="flex items-center gap-4 py-2">
                  <span className="flex-1 h-px bg-zinc-800" aria-hidden />
                  <span className="text-xs text-zinc-500 uppercase tracking-wider">OR</span>
                  <span className="flex-1 h-px bg-zinc-800" aria-hidden />
                </div>
                <div className="grid gap-4 sm:grid-cols-2">
                  <div className="space-y-2">
                    <Label htmlFor="coupleName" className="text-zinc-300">Couple's Name</Label>
                    <Input
                      id="coupleName"
                      placeholder="e.g. Priya & Rohan"
                      value={coupleName}
                      onChange={(e) => setCoupleName(e.target.value)}
                      className="bg-zinc-900 border-zinc-800 text-white placeholder:text-zinc-600"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="eventDate" className="text-zinc-300">Event Date</Label>
                    <Input
                      id="eventDate"
                      type="date"
                      value={eventDate}
                      onChange={(e) => setEventDate(e.target.value)}
                      className="bg-zinc-900 border-zinc-800 text-white [&::-webkit-calendar-picker-indicator]:invert"
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="email" className="text-zinc-300">Your Email</Label>
                  <Input
                    id="email"
                    type="email"
                    placeholder="e.g. you@example.com"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="bg-zinc-900 border-zinc-800 text-white placeholder:text-zinc-600"
                  />
                </div>
                {findError && (
                  <p className="text-sm text-red-400" role="alert">
                    {findError}
                  </p>
                )}
                <Button type="submit" disabled={isFinding} className="w-full bg-white text-black hover:bg-zinc-200 mt-2">
                  {isFinding ? "Searching…" : "Find My Album"}
                </Button>
                {albumData && (
                  <Button type="button" variant="outline" className="w-full border-zinc-700 text-zinc-300 hover:bg-zinc-800 mt-2" onClick={() => { setAlbumData(null); setIsSearchOpen(false); }}>
                    Back to Demo
                  </Button>
                )}
              </form>
            </DialogContent>
          </Dialog>

          <Dialog>
            <DialogTrigger asChild>
              <Button variant="secondary" size="icon" className="rounded-full bg-white/10 hover:bg-white/20 text-white border-white/20 backdrop-blur-md" title="Share">
                <Share2 className="h-4 w-4 sm:h-5 sm:w-5" />
              </Button>
            </DialogTrigger>
            <DialogContent className="sm:max-w-sm bg-zinc-950 text-white border-zinc-800 flex flex-col items-center text-center">
              <DialogHeader>
                <DialogTitle className="text-center">Share Album</DialogTitle>
                <DialogDescription className="text-center text-zinc-400">
                  Scan the code to view on another device.
                </DialogDescription>
              </DialogHeader>
              <div className="p-4 bg-white rounded-xl mt-4">
                {shareUrl ? (
                  <img
                    src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(shareUrl)}`}
                    alt="QR code to view album on another device"
                    width={200}
                    height={200}
                    className="rounded"
                  />
                ) : (
                  <div className="h-[200px] w-[200px] rounded bg-zinc-200 animate-pulse" />
                )}
              </div>
            </DialogContent>
          </Dialog>
        </div>
      </div>

      <div className="absolute inset-0 pt-24 pb-28 px-4 sm:px-12 flex items-center justify-center z-10 pointer-events-none">
        <div 
          ref={viewerRef} 
          className="w-full h-full max-w-[1600px] relative pointer-events-auto touch-none flex items-center justify-center"
          onTouchStart={handleTouchStart}
          onTouchEnd={handleTouchEnd}
        >
          {albumData && !albumData.url.toLowerCase().endsWith(".pdf") ? (
             <div 
               className="relative flex items-center justify-center origin-center transition-transform duration-200 ease-out"
               style={{
                  transform: `scale(${zoom})`,
                  width: '100%',
                  height: '100%',
               }}
             >
                <img
                  src={albumData.url}
                  alt={`Album: ${albumData.name}`}
                  className="max-w-full max-h-full object-contain drop-shadow-2xl rounded-sm"
                />
             </div>
          ) : (
            <div
              className="absolute origin-center transition-transform duration-200 ease-out flex items-center justify-center"
              style={{
                transform: `scale(${zoom})`,
              }}
              onClick={() => goNext()}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  goNext();
                }
              }}
              role="button"
              tabIndex={0}
              aria-label="Go to next page"
            >
              {pageWidth > 0 && pageHeight > 0 && (
                <Document
                  file={albumData ? albumData.url : PDF_URL}
                  onLoadSuccess={(pdf) => {
                    setNumPages(pdf.numPages);
                    pdf.getPage(1).then((page) => {
                      const v = page.getViewport({ scale: 1 });
                      setPdfPageDimensions({
                        width: v.width,
                        height: v.height,
                      });
                    });
                  }}
                  loading={
                    <div className="flex items-center justify-center text-white/50 animate-pulse">
                      Loading immersive experience...
                    </div>
                  }
                  error={
                    <div className="flex items-center justify-center text-red-400 bg-red-400/10 px-4 py-2 rounded-lg border border-red-400/20 backdrop-blur-md">
                      Failed to load PDF.
                    </div>
                  }
                >
                  {numPages != null && numPages > 0 && (
                    <HTMLFlipBook
                      ref={bookRef}
                      width={pageWidth}
                      height={pageHeight}
                      minWidth={pageWidth}
                      maxWidth={pageWidth}
                      minHeight={pageHeight}
                      maxHeight={pageHeight}
                      size="fixed"
                      showCover={false}
                      drawShadow={true}
                      flippingTime={800}
                      usePortrait={true}
                      startPage={0}
                      startZIndex={0}
                      autoSize={true}
                      maxShadowOpacity={0.8}
                      mobileScrollSupport={true}
                      clickEventForward={true}
                      useMouseEvents={true}
                      swipeDistance={30}
                      showPageCorners={true}
                      disableFlipByClick={false}
                      onFlip={onFlip}
                      onChangeState={onFlipState}
                      className="rounded-lg shadow-2xl overflow-hidden [&>div]:!w-full [&>div]:!h-full"
                      style={{
                        width: pageWidth * 2,
                        height: pageHeight,
                      }}
                    >
                      {Array.from({ length: numPages }, (_, i) => (
                        <PDFFlipPage
                          key={i}
                          pageNumber={i + 1}
                          width={pageWidth}
                          height={pageHeight}
                          pdfPageDimensions={pdfPageDimensions}
                        />
                      ))}
                    </HTMLFlipBook>
                  )}
                </Document>
              )}
            </div>
          )}
        </div>
      </div>

      <div className="absolute bottom-6 sm:bottom-10 left-1/2 -translate-x-1/2 z-50 pointer-events-auto">
        <div className="flex items-center justify-center gap-2 sm:gap-4 p-2 sm:p-3 rounded-full bg-white/10 border border-white/20 backdrop-blur-md shadow-2xl">
          <Button
            type="button"
            variant="ghost"
            size="icon"
            onClick={goPrev}
            disabled={currentPage <= 1 || isFlipping}
            className="text-white hover:bg-white/20 hover:text-white rounded-full h-10 w-10 sm:h-12 sm:w-12 disabled:opacity-30"
            aria-label="Previous page"
          >
            <ChevronLeft className="h-5 w-5 sm:h-6 sm:w-6" />
          </Button>
          
          <div className="w-px h-6 bg-white/20 mx-1" aria-hidden />
          
          <Button
            type="button"
            variant="ghost"
            size="icon"
            onClick={zoomOut}
            className="text-white hover:bg-white/20 hover:text-white rounded-full h-10 w-10 sm:h-12 sm:w-12"
            aria-label="Zoom out"
          >
            <ZoomOut className="h-4 w-4 sm:h-5 sm:w-5" />
          </Button>
          
          <Button
            type="button"
            variant="ghost"
            size="icon"
            onClick={zoomIn}
            className="text-white hover:bg-white/20 hover:text-white rounded-full h-10 w-10 sm:h-12 sm:w-12"
            aria-label="Zoom in"
          >
            <ZoomIn className="h-4 w-4 sm:h-5 sm:w-5" />
          </Button>
          
          <div className="w-px h-6 bg-white/20 mx-1" aria-hidden />

          <Button
            type="button"
            variant="ghost"
            size="icon"
            onClick={toggleFullscreen}
            className="text-white hover:bg-white/20 hover:text-white rounded-full h-10 w-10 sm:h-12 sm:w-12"
            aria-label={isFullscreen ? "Exit fullscreen" : "Fullscreen"}
          >
            {isFullscreen ? <Minimize2 className="h-4 w-4 sm:h-5 sm:w-5" /> : <Maximize className="h-4 w-4 sm:h-5 sm:w-5" />}
          </Button>

          <div className="w-px h-6 bg-white/20 mx-1" aria-hidden />

          <Button
            type="button"
            variant="ghost"
            size="icon"
            onClick={goNext}
            disabled={currentPage >= totalPages || isFlipping}
            className="text-white hover:bg-white/20 hover:text-white rounded-full h-10 w-10 sm:h-12 sm:w-12 disabled:opacity-30"
            aria-label="Next page"
          >
            <ChevronRight className="h-5 w-5 sm:h-6 sm:w-6" />
          </Button>
        </div>
      </div>
    </div>
  );
}
